  "htmlContent": "<div style='font-family:Montserrat,Arial,sans-serif;max-width:600px;margin:0 auto;padding:24px;background:#fff;color:#1A1A1A'><h2 style='color:#002292;margin:0 0 8px;font-family:Bricolage Grotesque,sans-serif;font-size:24px;letter-spacing:-0.025em'>Nuevo lead desde la web</h2><p style='margin:0 0 16px;font-size:14px;color:#5A5A5A'>Página de origen: <strong style='color:#002292'>{{ $json.origen }}</strong> · Tema de interés: <strong style='color:#002292'>{{ $json.sector_interes }}</strong></p><table style='width:100%;border-collapse:collapse;margin:20px 0;font-size:14px'><tr><td style='padding:10px;background:#E8EDFA;font-weight:600;width:130px'>Nombre</td><td style='padding:10px;background:#F5F4EE'>{{ $json.nombre }}</td></tr><tr><td style='padding:10px;background:#E8EDFA;font-weight:600'>Teléfono</td><td style='padding:10px;background:#F5F4EE'><a href='tel:{{ $json.telefono }}' style='color:#002292'>{{ $json.telefono }}</a></td></tr><tr><td style='padding:10px;background:#E8EDFA;font-weight:600'>Email</td><td style='padding:10px;background:#F5F4EE'><a href='mailto:{{ $json.email }}' style='color:#002292'>{{ $json.email }}</a></td></tr><tr><td style='padding:10px;background:#E8EDFA;font-weight:600;vertical-align:top'>Mensaje</td><td style='padding:10px;background:#F5F4EE;white-space:pre-wrap'>{{ $json.mensaje || '(sin mensaje)' }}</td></tr><tr><td style='padding:10px;background:#E8EDFA;font-weight:600'>URL origen</td><td style='padding:10px;background:#F5F4EE;font-size:12px;color:#6E6E6E'>{{ $json.url_origen }}</td></tr><tr><td style='padding:10px;background:#E8EDFA;font-weight:600'>Recibido</td><td style='padding:10px;background:#F5F4EE;font-size:12px;color:#6E6E6E'>{{ $json.enviado_en }}</td></tr></table><div style='margin:24px 0;text-align:center'><a href='https://crm.quenecesitashoy.com/leads-web' style='display:inline-block;background:#FF6A3D;color:white;padding:12px 24px;border-radius:10px;text-decoration:none;font-weight:600;font-size:14px'>Abrir lead en el CRM →</a></div><div style='margin-top:24px;padding:16px;background:#FFF4F0;border-left:3px solid #FF6A3D;font-size:13px;color:#1A1A1A;line-height:1.6'>Recuerda: contactar en menos de 24h laborables. El lead llegó desde {{ $json.origen }}.</div></div>"
